"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation


def _field(row: dict | None, name: str) -> object:
    if row is None:
        return ""
    value = row.get(name, "")
    return "" if value is None else value


def _number(value: object) -> Decimal:
    """Apply legacy numeric empty-value coercion."""
    if value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    """Implement legacy LOOKUP, including soft-delete invisibility."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _field(row, "DEL_FLG") == "Y":
            continue
        if _field(row, key_col) == key_val:
            return _field(row, out_col)

    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Return all applicable legacy validation failures in rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        disc_pct = _field(record, "DISC_PCT")

        # ORD-001
        if event in ("INSERT", "UPDATE"):
            if not (_number(disc_pct) >= Decimal(0) and _number(disc_pct) <= Decimal(100)):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        # ORD-002
        if event == "UPDATE":
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _field(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if _number(disc_pct) > Decimal(20) and role != "MGR" and role != "ADMIN":
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

        # ORD-003
        if event == "UPDATE":
            if (
                _field(old, "STAT_CD") == "I"
                and _field(record, "STAT_CD") != "I"
                and _field(record, "STAT_CD") != "X"
            ):
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in ("INSERT", "UPDATE"):
            if not _number(_field(record, "QTY")) > Decimal(0):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _field(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
